const conversations = $input.first().json;
const sessionId = $('Start').first().json.session_id;

// Build conversation transcript
const transcript = Array.isArray(conversations)
  ? conversations.map(c => `${c.role.toUpperCase()}: ${c.content}`).join('\n')
  : '';

return [{ json: { session_id: sessionId, transcript } }];

