const gptResp = $input.first().json;
const sessionId = $('Build Transcript').first().json.session_id;

let fields;
try {
  fields = JSON.parse(gptResp.choices[0].message.content);
} catch(e) {
  fields = { fields_still_needed: ['all'] };
}

// ── LEAD SCORING LOGIC ─────────────────────────────────────────────
let score = 0;

// Budget (30 pts)
const budget = (fields.monthly_budget || '').toLowerCase();
if (budget.includes('10k') || budget.includes('10,000') || budget.includes('$10')) score += 30;
else if (budget.includes('5k') || budget.includes('5,000') || budget.includes('$5')) score += 20;
else if (budget.includes('1k') || budget.includes('1,000') || budget.includes('$1')) score += 10;

// Company Size (25 pts)
const empCount = (fields.employee_count || '').toLowerCase();
if (empCount.includes('200+') || empCount.includes('500') || empCount.includes('1000')) score += 25;
else if (empCount.includes('51') || empCount.includes('100')) score += 20;
else if (empCount.includes('11') || empCount.includes('50')) score += 10;
else if (empCount.includes('1') || empCount.includes('10')) score += 5;

// Decision Maker (20 pts)
if (fields.decision_maker === true || fields.decision_maker === 'yes') score += 20;

// Urgency (15 pts)
const urgency = (fields.urgency || '').toLowerCase();
if (urgency.includes('immediate') || urgency.includes('now') || urgency.includes('asap')) score += 15;
else if (urgency.includes('1-3') || urgency.includes('month')) score += 10;

// Service Fit (10 pts)
const service = (fields.service_interest || '').toLowerCase();
if (service.includes('ai automation') || service.includes('custom ai') || service.includes('agent') || service.includes('n8n')) score += 10;
else if (service.includes('crm') || service.includes('lead') || service.includes('chatbot')) score += 7;
else if (service.includes('marketing') || service.includes('seo')) score += 5;

// Cap at 100
score = Math.min(score, 100);

// Categorise
let category;
if (score >= 75) category = 'hot';
else if (score >= 50) category = 'warm';
else category = 'cold';

// Check if qualification is complete (minimum required fields present)
const requiredFields = ['first_name', 'business_email', 'company', 'industry', 'monthly_budget', 'employee_count', 'business_challenge', 'decision_maker', 'urgency'];
const collectedCount = requiredFields.filter(f => fields[f] !== null && fields[f] !== undefined).length;
const isComplete = collectedCount >= 7; // 7 of 9 minimum

return [{
  json: {
    session_id: sessionId,
    ...fields,
    lead_score: score,
    lead_category: category,
    is_qualification_complete: isComplete,
    fields_collected_count: collectedCount,
    scored_at: new Date().toISOString()
  }
}];
